diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..28eb7db 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,46 @@ export interface Record {
   warns: readonly string[];
 }

+type Classification = "operational_burden" | "other";
+
+const classifyEntry = (entry: string): Classification => {
+  const operationalKeywords = /stateful|operate|operational|always.on|running|service|cache|infrastructure/i;
+  return operationalKeywords.test(entry) ? "operational_burden" : "other";
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+  const seenCategories = new Set<Classification>();
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const category = classifyEntry(entry);
+      if (category === "operational_burden" && seenCategories.has(category)) {
+        continue;
+      }
+      seenCategories.add(category);
+      lines.push(`- ruled out: ${entry}`);
+    }
+
+    seenCategories.clear();
+    for (const limit of record.limits) {
+      const category = classifyEntry(limit);
+      if (category === "operational_burden" && seenCategories.has(category)) {
+        continue;
+      }
+      seenCategories.add(category);
+      lines.push(`- limit: ${limit}`);
+    }
+
+    seenCategories.clear();
+    for (const warn of record.warns) {
+      const category = classifyEntry(warn);
+      if (category === "operational_burden" && seenCategories.has(category)) {
+        continue;
+      }
+      seenCategories.add(category);
+      lines.push(`- warn: ${warn}`);
+    }
   }
   return lines.join("\n");
 };
